import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"90-Day Action Plan: Return Your Life to Yourself","description":"A repeatable 90-day system for turning goals, baselines, output, feedback, artifacts, and health boundaries into visible change.","frontmatter":{"title":"90-Day Action Plan: Return Your Life to Yourself","description":"A repeatable 90-day system for turning goals, baselines, output, feedback, artifacts, and health boundaries into visible change.","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/part-5/90-day-plan.md","filePath":"en/threads/part-5/90-day-plan.md","lastUpdated":1795392000000}'),o={name:"en/threads/part-5/90-day-plan.md"};function r(s,e,l,h,d,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_90-day-action-plan-return-your-life-to-yourself" tabindex="-1">90-Day Action Plan: Return Your Life to Yourself <a class="header-anchor" href="#_90-day-action-plan-return-your-life-to-yourself" aria-label="Permalink to &quot;90-Day Action Plan: Return Your Life to Yourself&quot;">​</a></h1><p>Many people finish one piece of advice and immediately save another. Saving feels like a beginning, but it often moves the beginning somewhere more comfortable.</p><p>Progress depends less on a burst of excitement than on a stretch of time that can be inspected. This 90-day plan does not ask you to become a different person. It asks you to collect evidence that, three months from now, you can understand more, express more, and finish more. If you have not yet found a daily rhythm that can survive interruption, read <a href="./../part-4/rhythm-and-compounding">Rhythm: Let Small Things Travel Through Time</a> first, then give one returnable action to these 90 days.</p><h2 id="define-better" tabindex="-1">Define “Better” <a class="header-anchor" href="#define-better" aria-label="Permalink to &quot;Define “Better”&quot;">​</a></h2><p>Do not write “improve my English”, “learn AI”, or “become disciplined”. These wishes are fine, but they cannot guide today’s choice.</p><p>Use this sentence instead:</p><blockquote><p>Within 90 days, in <strong>a real situation</strong>, I will complete <strong>a deliverable</strong>, and judge it with <strong>three pieces of evidence</strong>.</p></blockquote><p>Examples:</p><ul><li>In 90 days, I will give a 10-minute product presentation in English. Evidence: a recording, transcript, and feedback from one listener.</li><li>In 90 days, I will build a small tool that organizes a spreadsheet. Evidence: runnable code, instructions, and one real use.</li><li>In 90 days, I will publish 12 short industry notes. Evidence: links, reader feedback, and a review of my own decisions.</li></ul><p>The closer the goal is to real life, the harder it is to hide behind “I am not ready yet”.</p><p>Copy the <a href="./../../templates/90-day-cycle">90-Day Cycle Map</a> first, then fill it with the phases and weekly questions below. It is not another check-in system; it puts the evidence you already collect on one timeline. Use the <a href="./../../templates/evidence-chain">Evidence Chain Template</a> to explain four time points and the <a href="./../../templates/rhythm-ledger">Rhythm Ledger</a> to maintain a weekly rhythm that can return.</p><h2 id="_1-take-a-one-page-baseline" tabindex="-1">1. Take a One-Page Baseline <a class="header-anchor" href="#_1-take-a-one-page-baseline" aria-label="Permalink to &quot;1. Take a One-Page Baseline&quot;">​</a></h2><p>On day one, spend 30 minutes writing four columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Question</th></tr></thead><tbody><tr><td>Current state</td><td>What can I do independently? Where do I stop?</td></tr><tr><td>Situation</td><td>Where will I use this ability in three months?</td></tr><tr><td>Resources</td><td>What time, material, tool, and person can I reliably access each week?</td></tr><tr><td>Cost</td><td>What must I do less of to make room for this goal?</td></tr></tbody></table><p>The last column matters most. A plan with no cost is only a wish list. Choosing one main line does not betray every other possibility; it gives one possibility enough light for a while.</p><h2 id="how-four-skills-join-the-same-cycle" tabindex="-1">How Four Skills Join the Same Cycle <a class="header-anchor" href="#how-four-skills-join-the-same-cycle" aria-label="Permalink to &quot;How Four Skills Join the Same Cycle&quot;">​</a></h2><p>You do not need equal listening, reading, speaking, and writing every week. Choose the skill closest to the real outcome, then use another skill for input or feedback:</p><table tabindex="0"><thead><tr><th>Part of the cycle</th><th>Role</th><th>Evidence to keep</th></tr></thead><tbody><tr><td>Listening/reading</td><td>Gather material, understand the problem, and locate evidence</td><td><a href="./../../templates/listening-audit">Listening Evidence Card</a> or <a href="./../../templates/reading-evidence">Reading Evidence Card</a></td></tr><tr><td>Speaking/writing</td><td>Turn understanding into an explanation, decision, or artifact</td><td><a href="./../../templates/speaking-evidence">Speaking Evidence Card</a> or <a href="./../../templates/writing-evidence">Writing Evidence Card</a></td></tr><tr><td>Feedback/review</td><td>Find the largest barrier and choose the next variable</td><td><a href="./../../templates/weekly-review">Weekly Review</a> and <a href="./../../templates/learning-state">Learning State</a></td></tr><tr><td>Delivery/transfer</td><td>Test the result with a new listener, topic, or real situation</td><td>Artifact link, user feedback, or parallel task</td></tr></tbody></table><p>If the four activities do not serve one outcome, they become unrelated check-ins again. Keep at least one input, one output, and one transfer test each week; let the rest support the main line.</p><h2 id="_2-three-phases" tabindex="-1">2. Three Phases <a class="header-anchor" href="#_2-three-phases" aria-label="Permalink to &quot;2. Three Phases&quot;">​</a></h2><h3 id="phase-one-calibrate-days-1–14" tabindex="-1">Phase One: Calibrate (days 1–14) <a class="header-anchor" href="#phase-one-calibrate-days-1–14" aria-label="Permalink to &quot;Phase One: Calibrate (days 1–14)&quot;">​</a></h3><p>Do not chase speed. Learn what is true.</p><ul><li>Take a baseline: record an English introduction or complete the smallest task in your field;</li><li>Find the three errors that appear most often;</li><li>Establish a fixed slot, even if it is only 25 minutes a day;</li><li>Keep one main resource, one practice situation, and one place to record results.</li></ul><p>At the end of two weeks, you should be able to answer: What exactly am I training? What is my bottleneck? What will I repeat next time? If you cannot answer, do not add more material.</p><h3 id="phase-two-stack-days-15–56" tabindex="-1">Phase Two: Stack (days 15–56) <a class="header-anchor" href="#phase-two-stack-days-15–56" aria-label="Permalink to &quot;Phase Two: Stack (days 15–56)&quot;">​</a></h3><p>Repeat one action until it becomes familiar, then raise the difficulty. Keep four kinds of work each week:</p><ol><li><strong>Input</strong>: two or three sessions of listening, reading, or example analysis;</li><li><strong>Output</strong>: two sessions of speaking, writing, coding, or presenting;</li><li><strong>Feedback</strong>: one concrete revision of a piece of work;</li><li><strong>Review</strong>: a 20-minute record of what to keep and what to remove next week.</li></ol><p>AI can be a coach, practice partner, reviewer, and tester. Do not let it complete every output. Submit your rough version first, then let the tool identify the most valuable repair. The repair you make yourself is where ability becomes yours.</p><h3 id="phase-three-ship-days-57–90" tabindex="-1">Phase Three: Ship (days 57–90) <a class="header-anchor" href="#phase-three-ship-days-57–90" aria-label="Permalink to &quot;Phase Three: Ship (days 57–90)&quot;">​</a></h3><p>From week eight, stop expanding the course. Concentrate what you have learned into one artifact: a talk, essay, tool, report, interview simulation, or real conversation.</p><p>Make three versions:</p><ul><li><strong>Independent</strong>: complete it without an answer key under realistic conditions;</li><li><strong>Revised</strong>: fix the problems that most affect understanding and results;</li><li><strong>Public</strong>: give it to a real person to use, read, or evaluate.</li></ul><p>The artifact does not need to win an award. It needs to be real enough to show your next direction.</p><h2 id="_3-one-main-question-per-week" tabindex="-1">3. One Main Question per Week <a class="header-anchor" href="#_3-one-main-question-per-week" aria-label="Permalink to &quot;3. One Main Question per Week&quot;">​</a></h2><p>Begin each week with one question, not ten tasks:</p><blockquote><p>Can I explain my work in English without reading from a script?</p></blockquote><p>Build the week around it:</p><ul><li>Monday: collect three natural expressions and hear them in context;</li><li>Tuesday: write a 90-second answer;</li><li>Wednesday: record it and mark pauses, repetition, and unclear sounds;</li><li>Thursday: ask AI or a partner to identify three high-value issues;</li><li>Friday: record a second version with one follow-up question;</li><li>Weekend: save the recording, revisions, and next week’s question together.</li></ul><p>At the end of the week you will have a chain of evidence instead of a pile of check-in screenshots. Put the first version, immediate performance, delayed retention, and transfer into the <a href="./../../templates/evidence-chain">Evidence Chain Template</a>, then write the decision back into the cycle map.</p><h2 id="_4-the-daily-minimum-loop" tabindex="-1">4. The Daily Minimum Loop <a class="header-anchor" href="#_4-the-daily-minimum-loop" aria-label="Permalink to &quot;4. The Daily Minimum Loop&quot;">​</a></h2><p>When life is fragmented, use this 45-minute version:</p><ol><li><strong>Recall for 5 minutes</strong>: write three things you remember without looking;</li><li><strong>Input for 15 minutes</strong>: work through a small section and mark only the difficulties that affect meaning;</li><li><strong>Output for 15 minutes</strong>: speak, write, build, or demonstrate a visible result;</li><li><strong>Feedback for 5 minutes</strong>: record one error and one reusable expression;</li><li><strong>Plan for 5 minutes</strong>: write the first action for tomorrow.</li></ol><p>If you have ten minutes, keep recall, output, and recording. Shorten the loop, but do not erase it.</p><h2 id="_5-when-you-fail-restart-the-next-step" tabindex="-1">5. When You Fail, Restart the Next Step <a class="header-anchor" href="#_5-when-you-fail-restart-the-next-step" aria-label="Permalink to &quot;5. When You Fail, Restart the Next Step&quot;">​</a></h2><p>Plans will be interrupted by illness, overtime, arguments, poor sleep, and unexpected bills. The interruption is not the failure. Turning it into a verdict about your character is what makes it grow.</p><p>Use this recovery protocol:</p><ol><li>Write the fact: I have not practiced for several days. Do not add a personality judgment;</li><li>Name the resistance: time, difficulty, mood, or an unsupportive environment;</li><li>Reduce the task to one third of its size;</li><li>Complete one tiny output within 24 hours;</li><li>Do not repay missed work by staying up late. Return to today.</li></ol><p>Long-term practice does not mean never falling behind. It means not punishing yourself with shame when you do.</p><h2 id="_6-an-honest-scorecard" tabindex="-1">6. An Honest Scorecard <a class="header-anchor" href="#_6-an-honest-scorecard" aria-label="Permalink to &quot;6. An Honest Scorecard&quot;">​</a></h2><p>Each Sunday, record only “done” or “not done”:</p><ul><li>Did I complete at least two active outputs?</li><li>Did I receive one concrete piece of feedback?</li><li>Did I turn one mistake into the next exercise?</li><li>Did I leave an artifact I can show or reuse?</li><li>Did I protect basic sleep, movement, and relationships?</li></ul><p>The last item is not a bonus. It is infrastructure. The body is not a container for your goals; it is part of your life. Any plan that requires chronic depletion needs redesign.</p><h2 id="_7-leave-three-things-after-90-days" tabindex="-1">7. Leave Three Things After 90 Days <a class="header-anchor" href="#_7-leave-three-things-after-90-days" aria-label="Permalink to &quot;7. Leave Three Things After 90 Days&quot;">​</a></h2><p>At the end, do not ask only how many days you checked off. Leave:</p><ol><li><strong>One artifact</strong> that proves you did more than study;</li><li><strong>One error map</strong> showing recurring problems and the next priorities;</li><li><strong>One sustainable rhythm</strong> that survives a busy week.</li></ol><p>If these three things exist, the 90 days were not wasted. You have built something more reliable than a disciplined-person image: trust that you know how to begin, revise, and finish.</p><h2 id="closing-return-progress-to-ordinary-days" tabindex="-1">Closing: Return Progress to Ordinary Days <a class="header-anchor" href="#closing-return-progress-to-ordinary-days" aria-label="Permalink to &quot;Closing: Return Progress to Ordinary Days&quot;">​</a></h2><p>I no longer trust the phrase “change your life completely”. It sounds powerful, but often leads to a larger disappointment. Real change usually has no soundtrack: someone gets up on time and opens yesterday’s file; says the first prepared sentence in a meeting; edits an article until they are willing to sign it; or, when escape feels urgent, looks at the facts first.</p><p>May the 90 days give you more than a skill. May they return a little texture to your contact with life. May you know where you are going, while accepting that the road may be quiet for a while.</p>',59)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
